package com.example.cvd;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import jakarta.annotation.PostConstruct;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/equipment/{equipmentId}/maintenance/qualification")
public class DummyApprovalApi {
 final DataStore db;final AccessStore access;
 public DummyApprovalApi(DataStore db,AccessStore access){this.db=db;this.access=access;}
 @PostConstruct void init(){db.pg.execute("CREATE TABLE IF NOT EXISTS dummy_confirmations(id text PRIMARY KEY,equipment_id text NOT NULL,maintenance_id text NOT NULL,run_id text NOT NULL,generation bigint NOT NULL,digest text NOT NULL,decision text NOT NULL,actor jsonb NOT NULL,evidence jsonb NOT NULL,reason text NOT NULL,created_at timestamptz DEFAULT now())");db.pg.execute("CREATE INDEX IF NOT EXISTS dummy_confirmation_cycle ON dummy_confirmations(equipment_id,maintenance_id,run_id,created_at DESC)");}
 static void lock(DataStore db,String eq){db.pg.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,7302042))",Object.class,eq);}
 static String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static ObjectNode evidence(DataStore db,String eq,JsonNode state){
  var m=state.path("maintenance");var run=m.path("run");var out=db.mapper.createObjectNode();out.put("equipmentId",eq).put("maintenanceId",m.path("id").asText()).put("generation",m.path("generation").asLong()).put("runId",run.path("id").asText()).put("recipeVersion",run.path("recipeVersion").asText());var rows=out.putArray("wafers");boolean passed=MaintenanceApi.held(state)&&run.path("status").asText().equals("passed")&&run.path("generation").asLong()==m.path("generation").asLong()&&run.path("recipeVersion").asText().equals(state.path("recipeVersion").asText());
  for(int i=1;i<=4;i++){String pm="PM"+i;var r=run.path("results").path(pm);String wafer=r.path("waferId").asText(),process=r.path("result").path("processRunId").asText();var entry=rows.addObject().put("pm",pm).put("waferId",wafer);boolean good=false;
   if(!wafer.isBlank()&&!process.isBlank()){String key=MetrologyApi.key(eq,wafer,process);var found=db.pg.queryForList("SELECT to_jsonb(r)::text FROM metrology_runs r WHERE equipment_id=? AND wafer_id=? AND source_key=? ORDER BY revision DESC LIMIT 1",String.class,eq,wafer,key);if(!found.isEmpty()){var met=db.parse(found.getFirst());var source=met.path("source");var result=met.path("result");entry.put("measurementId",met.path("id").asText()).put("revision",met.path("revision").asInt()).put("state",met.path("state").asText()).put("quality",result.path("thicknessQuality").asText());entry.set("source",source);entry.set("result",result);good=met.path("state").asText().equals("completed")&&!met.path("expired").asBoolean()&&source.path("purpose").asText().equals("dummy")&&source.path("pm").asText().equals(pm)&&source.path("lotId").asText().equals(run.path("lotId").asText())&&source.path("recipeVersion").asText().equals(run.path("recipeVersion").asText())&&MetrologyApi.validResult(result,source)&&result.path("thicknessQuality").asText().equals("pass");}}
   entry.put("passed",good);passed&=good&&r.path("complete").asBoolean()&&r.path("result").path("quality").asText().equals("pass");
  }out.put("passed",passed);return out;
 }
 static ObjectNode view(DataStore db,String eq,JsonNode state){var proof=evidence(db,eq,state);String hash=digest(proof.toString());var out=db.mapper.createObjectNode();out.set("evidence",proof);out.put("digest",hash);var m=state.path("maintenance");var confirmations=db.pg.queryForList("SELECT to_jsonb(c)::text FROM dummy_confirmations c WHERE equipment_id=? AND maintenance_id=? AND run_id=? ORDER BY created_at DESC,id DESC LIMIT 1",String.class,eq,m.path("id").asText(),m.path("run").path("id").asText());JsonNode c=confirmations.isEmpty()?db.mapper.createObjectNode():db.parse(confirmations.getFirst());boolean confirmed=proof.path("passed").asBoolean()&&c.path("digest").asText().equals(hash)&&c.path("decision").asText().equals("confirm");out.set("confirmation",c);out.put("confirmed",confirmed).put("canConfirm",proof.path("passed").asBoolean()&&!confirmed&&!c.path("decision").asText().equals("reject"));String status=confirmed?"approved":c.path("decision").asText().equals("reject")?"rejected":proof.path("passed").asBoolean()?"awaiting-pe":"awaiting-kla";out.put("status",status);return out;}
 @GetMapping public JsonNode current(){String eq=Equipment.current();return view(db,eq,db.parse(db.snapshot(eq)));}
 static void authorize(){var a=AccessSessions.actor();if(!"PE".equals(a.department())||!Set.of("Engineer","Leader").contains(a.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"需要 PE Engineer／Leader");}
 @PostMapping public JsonNode decide(@RequestBody ObjectNode body){authorize();String eq=Equipment.current();return access.tx.execute(tx->{lock(db,eq);String id=body.path("requestId").asText();try{UUID.fromString(id);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"invalid requestId");}var state=db.parse(db.snapshot(eq));if(!MaintenanceApi.fresh(state)||!state.path("communicationQuality").asText("good").equals("good")||state.path("dummyApprovalModelVersion").asInt()!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"設備資料過期或資格能力未就緒");var old=db.pg.queryForList("SELECT actor->>'id' actor FROM dummy_confirmations WHERE id=?",id);if(!old.isEmpty()){if(!AccessSessions.actor().id().equals(old.getFirst().get("actor")))throw new ResponseStatusException(HttpStatus.CONFLICT,"requestId already used");return view(db,eq,state);}var v=view(db,eq,state);var m=state.path("maintenance");String decision=body.path("decision").asText(),reason=body.path("reason").asText().trim();if(!Set.of("confirm","reject").contains(decision)||!v.path("digest").asText().equals(body.path("digest").asText())||!MaintenanceApi.held(state)||m.path("run").path("id").asText().isBlank())throw new ResponseStatusException(HttpStatus.CONFLICT,"驗證證據已變更，請重新載入");if(decision.equals("confirm")&&!v.path("canConfirm").asBoolean())throw new ResponseStatusException(HttpStatus.CONFLICT,"四片 KLA 尚未合格或本輪已退回");if(decision.equals("reject")&&reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"退回需填寫原因");if(Boolean.TRUE.equals(db.pg.queryForObject("SELECT EXISTS(SELECT 1 FROM commands WHERE equipment_id=? AND body->>'type'='resume' AND status IN ('received','accepted'))",Boolean.class,eq)))throw new ResponseStatusException(HttpStatus.CONFLICT,"復機指令待執行");db.pg.update("INSERT INTO dummy_confirmations(id,equipment_id,maintenance_id,run_id,generation,digest,decision,actor,evidence,reason) VALUES(?,?,?,?,?,?,?,?::jsonb,?::jsonb,?)",id,eq,m.path("id").asText(),m.path("run").path("id").asText(),m.path("generation").asLong(),v.path("digest").asText(),decision,db.mapper.valueToTree(AccessSessions.actor()).toString(),v.path("evidence").toString(),reason);access.audit(AccessSessions.actor(),"dummy-"+decision,m.path("id").asText(),id,v.path("digest").asText());return view(db,eq,state);});}
 static void guard(DataStore db,ObjectNode c,JsonNode state){String eq=c.path("equipmentId").asText();if(!MaintenanceApi.held(state)||!c.path("type").asText().equals("resume"))return;var v=view(db,eq,state);if(state.path("dummyApprovalModelVersion").asInt()!=1||!v.path("confirmed").asBoolean())throw new ResponseStatusException(HttpStatus.CONFLICT,"需完成四片 KLA 量測與 PE 合格確認");var p=(ObjectNode)c.path("parameters");p.set("dummyApproval",db.mapper.createObjectNode().put("confirmationId",v.path("confirmation").path("id").asText()).put("digest",v.path("digest").asText()).put("runId",state.path("maintenance").path("run").path("id").asText()).put("recipeVersion",state.path("recipeVersion").asText()));}
}
